package com.wams.quotation;
import com.wams.entity.*;import com.wams.operations.WeddingFunction;import com.wams.vendor.Vendor;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="quotation_requests",indexes={@Index(name="idx_quote_project",columnList="project_id,status"),@Index(name="idx_quote_vendor",columnList="vendor_id,status")})
@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder
public class QuotationRequest extends BaseEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="project_id",nullable=false)private WeddingProject project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="function_id")private WeddingFunction function;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_id",nullable=false)private Vendor vendor;@Column(nullable=false,length=150)private String service;@Column(nullable=false)private LocalDate deadline;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private QuotationStatus status;@Column(precision=14,scale=2)private BigDecimal amount;@Column(length=2000)private String description;private Instant submittedAt;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="decided_by_user_id")private User decidedBy;private Instant decidedAt;}
